CREATE TABLE [dbo].[th_documentos_firmados](
	[documento_id] [bigint] IDENTITY(1,1) NOT NULL,
	[empleado_id] [int] NOT NULL,
	[tipo_documento] [varchar](30) COLLATE Modern_Spanish_CI_AS NOT NULL,
	[accion_id] [int] NULL,
	[estudio_id] [int] NULL,
	[paz_salvo_id] [int] NULL,
	[origen_id]  AS (CONVERT([bigint],case when [tipo_documento]='FICHA_PERSONAL' then [empleado_id] when [tipo_documento]='ACCION_PERSONAL' then [accion_id] when [tipo_documento]='ESTUDIO_SOCIOECONOMICO' then [estudio_id] when [tipo_documento]='PAZ_SALVO' then [paz_salvo_id]  end)) PERSISTED,
	[version_documento] [int] NOT NULL,
	[nombre_original] [nvarchar](255) COLLATE Modern_Spanish_CI_AS NOT NULL,
	[ruta_privada] [nvarchar](500) COLLATE Modern_Spanish_CI_AS NOT NULL,
	[mime_type] [varchar](100) COLLATE Modern_Spanish_CI_AS NOT NULL,
	[tamano_bytes] [bigint] NOT NULL,
	[sha256] [char](64) COLLATE Modern_Spanish_CI_AS NOT NULL,
	[estado] [varchar](20) COLLATE Modern_Spanish_CI_AS NOT NULL,
	[observaciones] [nvarchar](500) COLLATE Modern_Spanish_CI_AS NULL,
	[usuario_carga] [varchar](50) COLLATE Modern_Spanish_CI_AS NOT NULL,
	[direccion_ip] [varchar](45) COLLATE Modern_Spanish_CI_AS NOT NULL,
	[fecha_carga] [datetime2](3) NOT NULL,
 CONSTRAINT [PK_th_documentos_firmados] PRIMARY KEY CLUSTERED 
(
	[documento_id] ASC
)WITH (PAD_INDEX = OFF, STATISTICS_NORECOMPUTE = OFF, IGNORE_DUP_KEY = OFF, ALLOW_ROW_LOCKS = ON, ALLOW_PAGE_LOCKS = ON)
)
